update borrow_record
book_id = #{bookId}, reader_id = #{readerId}, borrow_date = #{borrowDate}, due_date = #{dueDate}, return_date = #{returnDate}, fine_amount = #{fineAmount}, overdue_days = #{overdueDays}, status = #{status},
where id = #{id}

mapper.select:
select br.*,r.name from borrow_record br left join reader r on br.reader_id = r.id

    and r.name like concat('%',#{name},'%')
    and br.reader_id = #{readerId}
    and br.status = #{status}
